import { useCallback, useEffect, useState } from 'react';
import { SheetPanels } from '../../slots/defs/sheetPanels';
import { STATUSES, useClaims } from '../claims/useClaims';
import { useSheetTotals } from '../claims/useSheetTotals';
import { GRADES, usePeople } from '../people/usePeople';
import { hundredths, totalDue, trimmedTotal, useRates } from '../rates/useRates';
import { useSettings } from '../settings/useSettings';
import { useSheet } from '../sheet/useSheet';
import { useGradeDues } from '../summary/useGradeDues';
import { useDescendants } from './useDescendants';

type Figures = {
  /** Each person's names (their name and aliases, as names are compared). */
  names: string[][];
  /** Each person's due-total and overdue-total in cents (null: n/a), in the people's order. */
  dues: (string | null)[];
  overdues: (string | null)[];
  /** Per grade, the due-totals of the people not retired on it, added up. */
  grades: Record<string, string>;
  /** Per status, how many of the sheet's claims have it. */
  statuses: Record<string, number>;
};

const same = (a: Figures | null, b: Figures | null) =>
  a === b || (a !== null && b !== null && JSON.stringify(a) === JSON.stringify(b));

/** One sheet's figures as that sheet shows them (its header's people count, due-total and
 *  overdue-total), reported once everything they are worked out from has loaded. Renders nothing. */
function SheetFigures({ sheet, report }: { sheet: string; report: (sheet: string, figures: Figures | null) => void }) {
  const people = usePeople(sheet);
  const claims = useClaims(sheet);
  const rates = useRates(sheet);
  const settings = useSettings(sheet);
  const today = useSheet(sheet);
  const { perPerson } = useSheetTotals(sheet);
  const byGrade = useGradeDues(sheet);
  const ready = people.isSuccess && claims.isSuccess && rates.isSuccess && settings.isSuccess && today.isSuccess;
  const key = (n: string) => n.trim().toLowerCase();
  const names = JSON.stringify((people.data ?? []).map((p) => [p.name, ...p.aliases].map(key)));
  const cents = (c: bigint | null) => (c === null ? null : c.toString());
  const dues = JSON.stringify(perPerson.map((p) => cents(p.due)));
  const overdues = JSON.stringify(perPerson.map((p) => cents(p.overdue)));
  const grades = JSON.stringify(Object.fromEntries(GRADES.map((g) => [g, totalDue(byGrade[g].map((d) => d.due))])));
  const all = claims.data ?? [];
  const statuses = JSON.stringify(Object.fromEntries(STATUSES.map((s) => [s, all.filter((c) => c.status === s).length])));
  useEffect(() => {
    report(
      sheet,
      ready
        ? { names: JSON.parse(names), dues: JSON.parse(dues), overdues: JSON.parse(overdues), grades: JSON.parse(grades), statuses: JSON.parse(statuses) }
        : null,
    );
  }, [sheet, ready, names, dues, overdues, grades, statuses, report]);
  useEffect(() => () => report(sheet, null), [sheet, report]);
  return null;
}

/** How many people there are over the tree, counting once those whose names or aliases match (as
 *  names are compared), directly or through another person. */
function distinctPeople(names: string[][]): number {
  const parent = names.map((_, i) => i);
  const find = (i: number): number => (parent[i] === i ? i : (parent[i] = find(parent[i])));
  const seen = new Map<string, number>();
  names.forEach((keys, i) =>
    keys.forEach((k) => {
      const j = seen.get(k);
      if (j === undefined) seen.set(k, i);
      else parent[find(i)] = find(j);
    }),
  );
  return names.filter((_, i) => find(i) === i).length;
}

const toCents = (c: string | null) => (c === null ? null : BigInt(c));

/**
 * The consolidated figures over the sheet and all its descendants (see useDescendants): how many
 * people (counting once those whose names or aliases match, as names are compared), and the due-total
 * and overdue-total over every person of the tree, leaving out the single highest and lowest person's
 * figure over the whole tree when three or more have one; per grade,
 * each sheet's due-totals of the people not retired on it (as its summary shows them), added up; and
 * per status, how many claims have it over the tree. While the
 * screen shows the sheet as of a date, every sheet of the tree is read as it stood at the end of that
 * date, with that date as its today. A sheet
 * with no children shows its own. Blank until every sheet's figures have loaded.
 */
function Consolidated({ sheet }: { user: string; sheet: string }) {
  const { data: descendants } = useDescendants(sheet);
  const sheets = descendants === undefined ? [] : [sheet, ...descendants];
  const [figures, setFigures] = useState<Record<string, Figures | null>>({});
  const report = useCallback((id: string, f: Figures | null) => {
    setFigures((was) => (same(was[id] ?? null, f) ? was : { ...was, [id]: f }));
  }, []);
  const all = sheets.map((id) => figures[id] ?? null);
  const ready = sheets.length > 0 && all.every((f) => f !== null);
  const loaded = all.filter((f): f is Figures => f !== null);
  return (
    <section data-testid="consolidated">
      {sheets.map((id) => (
        <SheetFigures key={id} sheet={id} report={report} />
      ))}
      <p>
        Consolidated: people <strong data-testid="consolidated-people-count">{ready ? distinctPeople(loaded.flatMap((f) => f.names)) : ''}</strong>
        , due <strong data-testid="consolidated-due-total">{ready ? trimmedTotal(loaded.flatMap((f) => f.dues.map(toCents))) : ''}</strong>
        , overdue <strong data-testid="consolidated-overdue-total">{ready ? trimmedTotal(loaded.flatMap((f) => f.overdues.map(toCents))) : ''}</strong>
      </p>
      <p>
        Due by grade:
        {GRADES.map((g) => (
          <span key={g}>
            {' '}
            {g} <strong data-testid={`consolidated-grade-${g}-due-total`}>{ready ? totalDue(loaded.map((f) => hundredths(f.grades[g]))) : ''}</strong>
          </span>
        ))}
      </p>
      <p>
        Claims by status:
        {STATUSES.map((s) => (
          <span key={s}>
            {' '}
            {s} <strong data-testid={`consolidated-status-${s}-count`}>{ready ? loaded.reduce((n, f) => n + f.statuses[s], 0) : ''}</strong>
          </span>
        ))}
      </p>
    </section>
  );
}

export const contribution = SheetPanels.fill({ order: 21, Component: Consolidated });
import { gradeOn, heldOnBy, retiredOut, usePeople } from '../people/usePeople';
import { claimRateOn, rateOn, totalDue, trimmedTotal, useRates } from '../rates/useRates';
import { useCap, useFloor, useLate } from '../settings/useSettings';
import { useSheetToday } from '../sheet/useSheet';
import { carried, claimed, claimedLive, isOpen, live, overdueFigures, personDueCents, useClaims } from './useClaims';

/**
 * The sheet's totals: its claimed-total, everyone's counted (OPEN or SETTLED) claims added up
 * (held ones too, but not OPEN ones once their person retires, unless stated, nor those that correct another), and its due-total, everyone's due-total
 * added up (a person whose due-total is n/a is skipped), and how many of the claims that count are
 * overdue, with their dues added up. Both due and overdue totals leave out the single highest and
 * lowest person's figure when three or more people have one. Its settled-total and open-total are
 * everyone's due-total before the cap split into SETTLED and OPEN-or-PENDING claims, simply added up.
 * A person's figures carry their parts of the claims shared with them, and their own claims less the holders' parts. Each person's own figures too. One place, so every screen repeating a total shows the same figure.
 */
export function useSheetTotals(sheet: string) {
  const { data: all = [] } = useClaims(sheet);
  const { data: people = [] } = usePeople(sheet);
  const { data: rates = [] } = useRates(sheet);
  const today = useSheetToday(sheet);
  const claims = live(all, heldOnBy(people, today));
  const floor = useFloor(sheet);
  const late = useLate(sheet);
  const cap = useCap(sheet);
  // A claim's rate by its own person's grade on its date (a share holder's part is of that due).
  const byId = new Map(people.map((p) => [p.id, p]));
  const ownRate = (c: (typeof claims)[number]) => {
    const owner = byId.get(c.personId);
    return owner === undefined ? undefined : claimRateOn(rates, gradeOn(owner, c.date), c);
  };
  const dues = people.map((p) =>
    personDueCents(carried(claims, p.id), floor, rateOn(rates, gradeOn(p, today), today), ownRate, late, cap, p.id),
  );
  // Everyone's due-total before the cap, split into its SETTLED and its OPEN-and-PENDING part.
  const part = (keep: (c: (typeof claims)[number]) => boolean) =>
    people.map((p) =>
      personDueCents(carried(claims, p.id).filter(keep), floor, rateOn(rates, gradeOn(p, today), today), ownRate, late, undefined, p.id),
    );
  const over = people.map((p) =>
    overdueFigures(claims.filter((c) => c.personId === p.id), late, floor, (c) => claimRateOn(rates, gradeOn(p, c.date), c)),
  );
  return {
    /** Each person's own due-total (capped) and overdue-total, in cents, in the people's order. */
    perPerson: people.map((p, i) => ({ person: p, due: dues[i], overdue: over[i].cents })),
    claimedTotal: claimed(claimedLive(all, (id) => people.some((p) => p.id === id && retiredOut(p, today)))),
    dueTotal: trimmedTotal(dues),
    settledTotal: totalDue(part((c) => c.status === 'SETTLED')),
    openTotal: totalDue(part(isOpen)),
    overdueCount: over.reduce((n, o) => n + o.count, 0),
    overdueTotal: trimmedTotal(over.map((o) => o.cents)),
  };
}
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { dueCents, hundredths, roundTenThousandths } from '../rates/useRates';
import type { FloorOn } from '../settings/useSettings';
import { asOfKey, asOfPath, useAsOf } from '../asof/useAsOf';

/** Where a claim is in its life: DRAFT → OPEN → SETTLED (or, settled by a clerk over the clerk
 *  limit, OPEN → PENDING, which a steward approves to SETTLED or rejects back to OPEN), and DRAFT,
 *  OPEN or PENDING → VOID; a steward may void a SETTLED claim within 7 days of its settlement.
 *  A DRAFT whose due is above the sheet's review threshold on its date goes REVIEW when opened (no number
 *  yet) until a steward reviews it to OPEN; it can be voided, and counts in no total, only in the status counts.
 *  A DRAFT can be DELETED (and restored to DRAFT on the same sheet's today); a DELETED claim counts
 *  nowhere, not even in the status counts. */
export type ClaimStatus = 'DRAFT' | 'REVIEW' | 'OPEN' | 'PENDING' | 'SETTLED' | 'VOID' | 'DELETED';

/** Every status that is counted, in life order — the order the summary and header list them in (not DELETED). */
export const STATUSES: readonly ClaimStatus[] = ['DRAFT', 'REVIEW', 'OPEN', 'PENDING', 'SETTLED', 'VOID'];

/** Whether a claim is still open: OPEN or PENDING. A PENDING claim is handled like an OPEN one: it
 *  goes overdue, bears the late charge, and a hold takes it out of the totals. */
export function isOpen(claim: Claim): boolean {
  return claim.status === 'OPEN' || claim.status === 'PENDING';
}

/** A claim as the server sends it: `amount` with two decimals, `date` as yyyy-mm-dd. */
export type Claim = {
  id: number;
  personId: number;
  amount: string;
  date: string;
  note: string;
  status: ClaimStatus;
  /** Given when the claim is opened (a voided claim keeps it); null for a DRAFT, or a claim voided while a DRAFT. Sheet-wide ("7"), or within its period ("P1-2", "X-1" in no period). */
  number: string | null;
  /** The due fixed when the claim was settled, two decimals; null when it has none, so its due is live. */
  due: string | null;
  /** The user who opened the claim; null while it has not been opened. */
  openedBy: string | null;
  /** Whether the person's last statement binds the claim to the figure it had then. */
  stated: boolean;
  /** The figure the last statement bound the claim to, two decimals; null when unbound or bound to n/a. */
  statedDue: string | null;
  /** The number of the SETTLED claim of the same person a correction (a negative amount) corrects; null for any other claim. */
  corrects: string | null;
  /** Whether the claim's live figures (its rate step and late charge) round half up, else half to
   *  even: half up when it is dated before the sheet's policy date (a correction goes by the date of
   *  the claim it corrects). */
  halfUp: boolean;
  /** The date the claim is due by (yyyy-mm-dd), fixed when it was added from the terms of its
   *  person's grade then; later changes to the terms or the claim's date leave it. */
  dueBy: string;
  /** The claim's status log, oldest first: one line per status it has had, as
   *  "<STATUS> by <user> on <date> due=<due>" (the sheet's today and the claim's due then). */
  log: string[];
  /** Whether the claim is deferred now: OPEN, and the sheet's today is before its deferred-until
   *  date. A deferred claim counts in no total, is not overdue and cannot be settled. */
  deferred: boolean;
  /** The date (yyyy-mm-dd) the claim was last deferred until (kept once that date is reached); null when it never was. */
  deferredUntil: string | null;
  /** How many proofs the claim has: one whose due is above the sheet's proof threshold on its date
   *  cannot be settled or approved while it has none (nor while it lacks one of each of the sheet's proof kinds). */
  proofs: number;
  /** How many of its proofs are receipts (a proof added with no kind chosen is a receipt). */
  proofReceipts: number;
  /** How many of its proofs are photos. */
  proofPhotos: number;
  /** The number of the claim this one was split off; null when it was not split off one. */
  splitFrom: string | null;
  /** The user whose open editor locks the claim for everyone else; null when no editor holds it. */
  lockedBy: string | null;
  /** Whether the claim was added while its period was soft-closed. */
  lateEntry: boolean;
  /** The last day (yyyy-mm-dd) a reminder was written for the claim; null when it never was. */
  remindedOn: string | null;
  /** Whether a steward has waived the claim's late charge: it bears none from then on. */
  waived: boolean;
  /** Whether the claim is held: while OPEN or PENDING it counts in no live due figure (claimed still counts it), unless a statement binds it. */
  held: boolean;
  /** The claim's external reference, unique on the sheet without regard to case; null when it has none. */
  ref: string | null;

